import copy
import json
import math
from solution import solve


def close(actual, expected):
    if isinstance(expected, bool) or expected is None:
        return actual is expected
    if isinstance(expected, (int, float)):
        return isinstance(actual, (int, float)) and not isinstance(actual, bool) and math.isfinite(actual) and math.isclose(actual, expected, abs_tol=1e-9, rel_tol=1e-9)
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(close(a, e) for a, e in zip(actual, expected))
    if isinstance(expected, dict):
        return isinstance(actual, dict) and actual.keys() == expected.keys() and all(close(actual[k], v) for k, v in expected.items())
    return actual == expected


CASES = json.loads("[{\"name\":\"leaf\",\"input\":{\"network\":{\"kind\":\"resistor\",\"ohms\":12}},\"expected\":{\"ohms\":12}},{\"name\":\"equal_parallel\",\"input\":{\"network\":{\"kind\":\"parallel\",\"children\":[{\"kind\":\"resistor\",\"ohms\":10},{\"kind\":\"resistor\",\"ohms\":10}]}},\"expected\":{\"ohms\":5}}]")
for case in CASES:
    value = copy.deepcopy(case["input"])
    assert close(solve(value), case["expected"]), case["name"]
    assert value == case["input"], "Do not mutate the input"
print("Public examples passed")

