def solve(payload):
    def equivalent(node):
        kind = node["kind"]
        if kind == "resistor":
            if node["ohms"] < 0:
                raise ValueError()
            return node["ohms"]
        if kind not in ("series", "parallel") or not node["children"]:
            raise ValueError()
        values = [equivalent(child) for child in node["children"]]
        if kind == "series":
            return sum(values)
        if any(r == 0 for r in values):
            return 0
        return 1/sum(1/r for r in values)
    try:
        return {"ohms": equivalent(payload["network"])}
    except ValueError:
        return {"error": "invalid_network"}

